/*
 * (1) COMPOSITION: backdrop gradient plane at z=-2.5; testimonial panel 3.4x1.9 slightly right-offset;
 *     oversized red quote mark top-left, quote below, accent rule + attribution + caption at bottom.
 * (2) LIGHT RIG: rig-soft-wrap — warm key dir 2.0 @ [1.8,2.2,2.8], hemisphere fill 0.5, rim dir 0.9 @ [-1,1.8,-2.4], ambient 0.24.
 * (3) MATERIALS: panel MeshPhysicalNodeMaterial with TSL vertical gradient #1a1a22->#111116, rough 0.6/metal 0.2/clearcoat 0.1,
 *     hairline border #26262f via TSL edge mask; extruded quote mark box #ff2a38 rough 0.5/metal 0.3.
 * (4) MOTION: fade-up (opacity 0->1, y +0.2->0, 0.5s power2.out) then quote-mark weighted-settle 1.04->1.0 over 0.9s power4.out. No idle.
 * (5) FOCAL: the signal-red extruded quotation mark — the single brightest element.
 */
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
} from 'three/webgpu';
import { uv, vec3, mix, smoothstep, color, float, step, min, max, abs, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry, DirectionalLight, HemisphereLight, AmbientLight } = THREE;

  const root = new Group();
  root.name = 'testimonial-panel';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  const vs = config.intent?.visualSpec ?? {};
  const colors = vs.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#16161d',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
    grad0: colors.gradientStops?.[0]?.hex ?? '#1a1a22',
    grad1: colors.gradientStops?.[1]?.hex ?? '#111116',
  };

  // ---------- backdropStage: graded stage, never void (color.background, color.gradient context)
  const backdropMat = new MeshBasicNodeMaterial();
  const bgTop = vec3(...new THREE.Color(C.grad0).toArray());
  const bgBot = vec3(...new THREE.Color(C.background).toArray());
  backdropMat.colorNode = mix(bgBot, bgTop.mul(0.85), smoothstep(0.0, 1.0, uv().y).mul(0.7).add(uv().x.sub(0.5).abs().oneMinus().mul(0.12)));
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- lightRig: rig-soft-wrap (subject radius ~1.7)
  const R = 1.7;
  const ambient = new AmbientLight(0xffffff, 0.24);
  const key = new DirectionalLight(0xffefdd, 1.4);
  key.position.set(1.8 * R, 2.2 * R, 2.8 * R);
  key.target.position.set(0, 0.5, 0);
  const fill = new HemisphereLight(0xefe8de, 0x16161d, 0.5);
  const rim = new DirectionalLight(0xfff8f0, 0.9);
  rim.position.set(-1 * R, 1.8 * R, -2.4 * R);
  rim.target.position.set(0, 0.5, 0);
  root.add(ambient, key, key.target, fill, rim, rim.target);

  // ---------- panelGroup: the animated unit
  const panel = new Group();
  panel.name = 'panel';
  root.add(panel);

  // ---------- panelSurface: 3.4 x 1.9 gradient slab with hairline border (effects.spec, color.gradient, color.surface)
  const PW = 3.4, PH = 1.9, PD = 0.06;
  const panelMat = new MeshPhysicalNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
  });
  const g0 = vec3(...new THREE.Color(C.grad0).toArray());
  const g1 = vec3(...new THREE.Color(C.grad1).toArray());
  const border = vec3(...new THREE.Color('#26262f').toArray());
  const u = uv();
  // vertical gradient top(#1a1a22) -> bottom(#111116)
  const albedo = mix(g1, g0, u.y);
  // hairline border 0.006 units -> normalized per axis
  const bx = float(0.006 / PW);
  const by = float(0.006 / PH);
  const edge = min(min(u.x, u.x.oneMinus()).div(bx), min(u.y, u.y.oneMinus()).div(by));
  const borderMask = smoothstep(0.0, 1.0, edge).oneMinus();
  panelMat.colorNode = mix(albedo, border, borderMask);
  const panelGeo = new BoxGeometry(PW, PH, PD);
  const panelMesh = new Mesh(panelGeo, panelMat);
  panelMesh.position.set(0, 0, 0);
  panel.add(panelMesh);
  disposables.push(panelGeo, panelMat);

  // contact shadow (grounding, radial fade)
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = smoothstep(1.0, 0.15, uv().sub(0.5).length().mul(2.0)).mul(0.5);
  const shadowGeo = new CircleGeometry(2.2, 40);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.25, 0.2);
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- text content bridge
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.find((i) => i.role === role);
  const quoteMarkItem = byRole('quote-mark') ?? items[0];
  const quoteItem = byRole('quote') ?? items[1];
  const attrItem = byRole('attribution') ?? items[2];
  const captionItem = byRole('caption') ?? items[3];

  const PAD = 0.5;
  const LEFT = -PW / 2 + PAD;
  const TOP = PH / 2 - PAD;
  const TEXT_Z = PD / 2 + 0.03;

  // ---------- quoteMarkGroup: FOCAL — extruded red slab behind MSDF glyph (text.quote-mark.0, color.accent)
  const markGroup = new Group();
  const markSlabMat = new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.3 });
  markSlabMat.colorNode = vec3(...new THREE.Color(C.accent).toArray());
  const markSlabGeo = new BoxGeometry(0.5, 0.62, 0.04);
  const markSlab = new Mesh(markSlabGeo, markSlabMat);
  markSlab.position.set(0, 0, PD / 2 + 0.02);
  markGroup.add(markSlab);
  disposables.push(markSlabGeo, markSlabMat);

  const markText = ctx.fontAtlas.createText(String(quoteMarkItem?.text ?? '"'), {
    fontSize: 62,
    color: C.paper,
    align: 'center',
  });
  markText.position.set(0, 0, PD / 2 + 0.045);
  markGroup.add(markText);
  markGroup.position.set(LEFT + 0.25, TOP - 0.31, 0);
  panel.add(markGroup);

  // ---------- quoteText (text.quote.1, color.paper)
  const quoteText = ctx.fontAtlas.createText(
    String(quoteItem?.text ?? 'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.'),
    { fontSize: 20, color: C.paper, align: 'left', maxWidthPx: 480 }
  );
  quoteText.position.set(LEFT, TOP - 0.62 - 0.25, TEXT_Z);
  panel.add(quoteText);

  // ---------- attributionRow: accent rule + name + caption (text.attribution.2, text.caption.3, color.accent)
  const ruleMat = new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.2 });
  ruleMat.colorNode = vec3(...new THREE.Color(C.accent).toArray());
  ruleMat.emissiveNode = vec3(...new THREE.Color(C.accent).toArray()).mul(1.4);
  const ruleGeo = new BoxGeometry(0.2, 0.02, 0.015);
  const rule = new Mesh(ruleGeo, ruleMat);
  const attrY = TOP - 0.62 - 0.25 - 0.55 - 0.25;
  rule.position.set(LEFT + 0.1, attrY, TEXT_Z);
  panel.add(rule);
  disposables.push(ruleGeo, ruleMat);

  const attrText = ctx.fontAtlas.createText(String(attrItem?.text ?? 'M. OKAFOR'), {
    fontSize: 13,
    color: C.paper,
    align: 'left',
    letterSpacingPx: 1.04,
  });
  attrText.position.set(LEFT + 0.28, attrY, TEXT_Z);
  panel.add(attrText);

  const captionText = ctx.fontAtlas.createText(String(captionItem?.text ?? 'COLLECTOR SINCE 2019'), {
    fontSize: 9,
    color: '#9aa0ab',
    align: 'left',
    letterSpacingPx: 1.08,
  });
  captionText.position.set(LEFT + 0.28, attrY - 0.13, TEXT_Z);
  panel.add(captionText);

  // ---------- mountMotion: fade-up then weighted-settle; no idle motion
  const collectMats = (obj) => {
    const mats = [];
    obj.traverse((o) => { if (o.material) mats.push(o.material); });
    return mats;
  };
  const fadeMats = collectMats(panel);
  fadeMats.forEach((m) => { m.transparent = true; m.opacity = 0; });

  panel.position.y = -0.2;
  const tl = gsap.timeline();
  tl.to(panel.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
  fadeMats.forEach((m) => tl.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0));
  markGroup.scale.setScalar(1.04);
  tl.to(markGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.5);
  timelines.push(tl);

  // ---------- primitives (spec ships none, but honor any provided)
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives?.[p.name];
    if (fn) primHandles.push(fn(panel, p.params ?? {}));
  }

  // ---------- cleanup
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primHandles.forEach((h) => h?.cleanup?.());
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        (Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => {
          m.map?.dispose?.();
          m.dispose?.();
        });
      }
    });
    disposables.forEach((d) => d.dispose?.());
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.quote-mark.0","where":"quoteMarkGroup","how":"MSDF glyph on extruded accent slab"},
{"id":"text.quote.1","where":"quoteText","how":"MSDF quote at fontSize 20, floated +0.03z"},
{"id":"text.attribution.2","where":"attributionRow","how":"MSDF mono attribution beside accent rule"},
{"id":"text.caption.3","where":"attributionRow","how":"MSDF caption below attribution"},
{"id":"color.background","where":"backdropStage","how":"gradient bottom stop #0b0b10"},
{"id":"color.surface","where":"lightRig","how":"hemisphere ground color #16161d"},
{"id":"color.ink","where":"panelSurface","how":"dark panel body tones from ink family"},
{"id":"color.paper","where":"quoteText","how":"#e8ecf2 on quote, mark, attribution"},
{"id":"color.accent","where":"quoteMarkGroup","how":"red mark slab and emissive rule"},
{"id":"color.gradient","where":"panelSurface","how":"TSL vertical mix #1a1a22 to #111116"},
{"id":"effects.spec","where":"panelSurface","how":"3.4x1.9 slab, border, PBR, padding grid"}
]}
*/
